sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var profileSysId = current.getUniqueValue();
    var profile = new GlideRecord('x_2311790_skills_0_student_profile');
    if (!profile.get(profileSysId))
        return;

    if (profile.getValue('u_parse_status') != 'pending')
        return;

    var attempts = parseInt(profile.getValue('u_parse_attempts') || '0', 10);
    if (isNaN(attempts))
        attempts = 0;

    var expectedAttachment = profile.getValue('u_parsed_attachment_sys_id') || '';
    var gemini = new x_2311790_skills_0.GeminiUtils();
    var result = gemini.parseResumeAttachment(profile.getTableName(), profile.getUniqueValue());

    if (result && result.ok) {
        if (expectedAttachment && result.attachmentSysId && expectedAttachment != result.attachmentSysId) {
            gs.warn('Parse Resume When Pending: skipped stale result for ' + profileSysId + '. Expected attachment ' + expectedAttachment + ', got ' + result.attachmentSysId);
            return;
        }

        var data = result.data || {};
        if (!data.skills || !data.tools) {
            failParse('MISSING_STRUCTURED_DATA', 'Gemini result did not include structured skills.', attempts, profile, profileSysId);
            return;
        }

        var writer = new x_2311790_skills_0.StructuredSkillsWriter();
        var writeResult = writer.write(profileSysId, data);
        if (!writeResult || !writeResult.ok) {
            var writeCode = (writeResult && writeResult.errorCode) || 'UNKNOWN_WRITE_FAILURE';
            var writeMessage = (writeResult && writeResult.errorMessage) || 'Structured skills could not be written.';
            failParse('SKILL_WRITE_FAILED:' + writeCode, writeMessage, attempts, profile, profileSysId);
            return;
        }

        profile.setValue('u_parse_attempts', attempts + 1);
        profile.setValue('u_headline', data.headline || '');
        profile.setValue('u_parsed_resume', data.parsed_resume || '');
        profile.setValue('u_education', data.education || '');
        profile.setValue('u_experience_years', data.experience_years || 0);
        profile.setValue('u_projects', data.projects || '');
        profile.setValue('u_parsed_attachment_sys_id', result.attachmentSysId || expectedAttachment);
        profile.setValue('u_parse_status', 'parsed');
        profile.setValue('u_parse_error', '');
        profile.update();
        return;
    }

    var code = (result && result.errorCode) || 'UNKNOWN_FAILURE';
    var message = (result && result.errorMessage) || 'Resume parsing failed.';
    failParse(code, message, attempts, profile, profileSysId);

    function failParse(code, message, attempts, profile, profileSysId) {
        var storedMessage = code + ': ' + message;
        if (storedMessage.length > 997)
            storedMessage = storedMessage.substring(0, 997) + '...';

        profile.setValue('u_parse_attempts', attempts + 1);
        profile.setValue('u_parse_status', 'failed');
        profile.setValue('u_parse_error', storedMessage);
        profile.update();

        gs.warn('Parse Resume When Pending: ' + code + ' for ' + profileSysId);
    }
})(current, previous);
